            password: process.env.DB_PASSWORD || 'postgres',
            database: process.env.DB_DATABASE || 'aviturismo_db',
        });
    await client.connect();
    try {
        for (const table of data.tables) {
            if (!table.values || table.values.length === 0)
                continue;
            let tableName = table.name;
            if (tableName === 'beak_morphology')
                tableName = 'beak_morphologies';
            if (tableName === 'wing_morphology')
                tableName = 'wing_morphologies';
            if (tableName === 'leg_morphology')
                tableName = 'leg_morphologies';
            if (tableName === 'tail_morphology')
                tableName = 'tail_morphologies';
            if (tableName === 'users' || tableName === 'sightings')
                continue;
