                try {
                    await client.query(query, values);
                    inserted++;
                }
                catch (e) {
                    console.error(`Error in ${tableName} with query: ${query}`);
                    console.error(e.message);
                    break;
                }
            }
            console.log(`Successfully inserted ${inserted} rows into ${tableName}.`);
        }
    }
    catch (err) {
        console.error('Error seeding', err);
    }
