import { inject } from '@angular/core';
import { catchError, throwError } from 'rxjs';
import { UiService } from '../services/ui.service';

/**
 * @param req
 * @param next
 * @function errorInterceptor
 * @description Centinela de red FlockApp. Captura fallos 400/404 y libera la UI.
 */
export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const ui = inject(UiService);

  return next(req).pipe(
    catchError((error: HttpErrorResponse) => {
      // 1. Prioridad Máxima: Liberar la interfaz (R2)
      ui.dismissLoading();

      let errorMessage = 'Error de conexión con FlockApp';

      // 2. Extracción profunda del mensaje del Backend
      if (error.error) {
        if (typeof error.error.message === 'string') {
          errorMessage = error.error.message;
        } else if (Array.isArray(error.error.message)) {
          errorMessage = error.error.message[0];
        } else if (error.error.error) {
          // Casos donde NestJS envía el error plano
          errorMessage = error.error.error;
        }
      }

      // 3. Notificación visual mediante el UiService del usuario (R1)
      ui.showToast(`${errorMessage}`, 'danger');

      return throwError(() => error);
    }),
  );
};

import { HttpInterceptorFn, HttpErrorResponse } from '@angular/common/http';
import { inject } from '@angular/core';
import { throwError } from 'rxjs';
import { NetworkService } from '../services/network.service';

/**
 * @param req
 * @param next
 * @sdd
 * @description Centinela Híbrido: Bloquea inmediatamente peticiones a endpoints Online-Only
 * si el dispositivo se encuentra Offline, previniendo timeouts largos.
 */
export const networkInterceptor: HttpInterceptorFn = (req, next) => {
  const network = inject(NetworkService);

  // Definir prefijos o patrones de rutas que requieren conexión estricta a Postgres
  const onlineOnlyEndpoints = ['/v1/feed', '/v1/users', '/v1/guides'];

  const isOnlineOnlyRequest = onlineOnlyEndpoints.some((endpoint) => req.url.includes(endpoint));

  if (isOnlineOnlyRequest && !network.isOnline()) {
    // Abortar la petición y generar un error simulado para el errorInterceptor
    const offlineError = new HttpErrorResponse({
      error: { message: 'No tienes conexión a internet. Esta acción requiere estar en línea.' },
      status: 503,
      statusText: 'Service Unavailable (Offline)',
      url: req.url,
    });
    return throwError(() => offlineError);
  }

  return next(req);
};

/**
 * @sdd
 * [Objetivo]: Servicio centralizado para auditoría, consulta reactiva y solicitud con revelación previa (Google Play Rationale) de permisos de Android (Cámara, GPS, Multimedia).
 * [I/O]: Expone Signals de estado (cameraStatus, locationStatus, photosStatus) y métodos asíncronos requestCameraWithRationale(), requestLocationWithRationale(), requestPhotosWithRationale(), checkAllPermissions(), showDeviceSettingsGuide().
 * [Edge Cases]: Plataforma Web (degradación elegante), permisos denegados permanentemente (guía paso a paso para Ajustes del SO), errores de plugin nativo.
 */
import { Injectable, inject, signal } from '@angular/core';
import { ModalController, AlertController } from '@ionic/angular';
import { Camera, PermissionStatus as CameraPermissionStatus } from '@capacitor/camera';
import { Geolocation, PermissionStatus as GeoPermissionStatus } from '@capacitor/geolocation';
import { Capacitor } from '@capacitor/core';
import {
  PermissionRationaleModalComponent,
  PermissionRationaleType,
} from '../../shared/components/permission-rationale-modal/permission-rationale-modal.component';

/** Tipo que representa el estado consolidado de un permiso */
export type AppPermissionState = 'prompt' | 'granted' | 'denied';

/**
 * Servicio de permisos para la aplicación móvil FlockApp.
 */
@Injectable({
  providedIn: 'root',
})
export class AppPermissionsService {
  /** Controlador modal de Ionic */
  private readonly modalCtrl = inject(ModalController);

  /** Controlador de alertas de Ionic */
  private readonly alertCtrl = inject(AlertController);

  /** Estado reactivo del permiso de cámara */
  public readonly cameraStatus = signal<AppPermissionState>('prompt');

  /** Estado reactivo del permiso de ubicación GPS */
  public readonly locationStatus = signal<AppPermissionState>('prompt');

  /** Estado reactivo del permiso de fotos y galería */
  public readonly photosStatus = signal<AppPermissionState>('prompt');

  /**
   * Constructor del servicio. Inicializa la verificación pasiva de permisos.
   */
  constructor() {
    void this.checkAllPermissions();
  }

  /**
   * Consulta el estado de todos los permisos sensibles y actualiza los signals reactivos.
   */
  async checkAllPermissions(): Promise<void> {
    try {
      if (Capacitor.isNativePlatform()) {
        const camResult: CameraPermissionStatus = await Camera.checkPermissions();
        this.cameraStatus.set(this.normalizeStatus(camResult.camera));
        this.photosStatus.set(this.normalizeStatus(camResult.photos));

        const geoResult: GeoPermissionStatus = await Geolocation.checkPermissions();
        this.locationStatus.set(this.normalizeStatus(geoResult.location));
      } else {
        // En entorno Web, verificar APIs del navegador si están disponibles
        if ('permissions' in navigator) {
          try {
            const geoPerm = await navigator.permissions.query({ name: 'geolocation' as PermissionName });
            this.locationStatus.set(this.normalizeStatus(geoPerm.state));
          } catch {
            this.locationStatus.set('prompt');
          }
        }
      }
    } catch {
      // Degradación silenciosa en entornos de test o navegadores restrictivos
    }
  }

  /**
   * Solicita el permiso de cámara presentando primero la modal de revelación requerida por Google Play.
   * @returns Promise<boolean> true si el permiso fue concedido, false de lo contrario.
   */
  async requestCameraWithRationale(): Promise<boolean> {
    await this.checkAllPermissions();
    if (this.cameraStatus() === 'granted') {
      return true;
    }

    if (this.cameraStatus() === 'denied') {
      await this.showDeviceSettingsGuide('camera');
      return false;
    }

    const accepted = await this.presentRationaleModal('camera');
    if (!accepted) {
      return false;
    }

    try {
      const result = await Camera.requestPermissions({ permissions: ['camera'] });
      const status = this.normalizeStatus(result.camera);
      this.cameraStatus.set(status);
      return status === 'granted';
    } catch {
      return false;
    }
  }

  /**
   * Solicita el permiso de ubicación GPS presentando primero la modal de revelación requerida por Google Play.
   * @returns Promise<boolean> true si el permiso fue concedido, false de lo contrario.
   */
  async requestLocationWithRationale(): Promise<boolean> {
    await this.checkAllPermissions();
    if (this.locationStatus() === 'granted') {
      return true;
    }

    if (this.locationStatus() === 'denied') {
      await this.showDeviceSettingsGuide('location');
      return false;
    }

    const accepted = await this.presentRationaleModal('location');
    if (!accepted) {
      return false;
    }

    try {
      const result = await Geolocation.requestPermissions({ permissions: ['location', 'coarseLocation'] });
      const status = this.normalizeStatus(result.location);
      this.locationStatus.set(status);
      return status === 'granted';
    } catch {
      return false;
    }
  }

  /**
   * Solicita el permiso de acceso a fotos presentando primero la modal de revelación.
   * @returns Promise<boolean> true si el permiso fue concedido, false de lo contrario.
   */
  async requestPhotosWithRationale(): Promise<boolean> {
    await this.checkAllPermissions();
    if (this.photosStatus() === 'granted') {
      return true;
    }

    if (this.photosStatus() === 'denied') {
      await this.showDeviceSettingsGuide('photos');
      return false;
    }

    const accepted = await this.presentRationaleModal('photos');
    if (!accepted) {
      return false;
    }

    try {
      const result = await Camera.requestPermissions({ permissions: ['photos'] });
      const status = this.normalizeStatus(result.photos);
      this.photosStatus.set(status);
      return status === 'granted';
    } catch {
      return false;
    }
  }

  /**
   * Muestra la modal de revelación obligatoria de Google Play antes del diálogo del sistema.
   * @param type Tipo de permiso solicitado
   * @returns Promise<boolean> true si el usuario confirmó continuar
   */
  private async presentRationaleModal(type: PermissionRationaleType): Promise<boolean> {
    const modal = await this.modalCtrl.create({
      component: PermissionRationaleModalComponent,
      componentProps: { permissionType: type },
      backdropDismiss: false,
      cssClass: 'permission-rationale-dialog',
    });

    await modal.present();
    const { data } = await modal.onDidDismiss<{ confirmed?: boolean }>();
    return Boolean(data?.confirmed);
  }

  /**
   * Muestra guía amigable de ajustes del sistema cuando un permiso fue denegado permanentemente.
   * @param type Tipo de permiso denegado
   */
  async showDeviceSettingsGuide(type: PermissionRationaleType): Promise<void> {
    const nameMap: Record<PermissionRationaleType, string> = {
      camera: 'Cámara',
      location: 'Ubicación (GPS)',
      photos: 'Fotos y Multimedia',
    };

    const permName = nameMap[type] || 'este permiso';

    const alert = await this.alertCtrl.create({
      header: `Permiso de ${permName} Desactivado`,
      subHeader: 'Requiere activación manual en Android',
      message: `El permiso de ${permName} fue denegado previamente. Para activarlo:\n\n1. Abre los Ajustes de tu teléfono Android.\n2. Ve a Aplicaciones > FlockApp.\n3. Selecciona 'Permisos' y activa ${permName}.`,
      buttons: [
        {
          text: 'Entendido',
          role: 'cancel',
        },
      ],
    });

    await alert.present();
  }

  /**
   * Normaliza los diferentes estados de permisos de Capacitor a una terna unificada.
   * @param rawStatus Estado devuelto por el plugin
   * @returns {AppPermissionState} Estado normalizado
   */
  private normalizeStatus(rawStatus?: string): AppPermissionState {
    if (!rawStatus) return 'prompt';
    if (rawStatus === 'granted') return 'granted';
    if (rawStatus === 'denied') return 'denied';
    return 'prompt';
  }
}

import { Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { User, AuthResponse } from '../models/auth.models';
import { DbHelperService } from './db-helper.service';
import { CryptoService } from './crypto.service';
import { environment } from '../../../environments/environment';

/**
 * @sdd
 * [Objetivo]: Servicio core de identidad. Gestiona la comunicación con los endpoints
 * de NestJS para autenticación, registro y recuperación de cuenta.
 * [I/O]: Depende de HttpClient, DbHelperService, CryptoService.
 * Expone: login(), register(), forgotPassword(), verifyOtp(), resetPassword(), logout()
 * [Edge Cases]: Token almacenado en RAM volátil. Sesión persistida en SQLite/localStorage
 * solo si remember=true. RSA fallback si encriptación falla.
 */
@Injectable({
  providedIn: 'root',
})
export class AuthService {
  /** @description Cliente HTTP para peticiones REST. */
  private readonly http = inject(HttpClient);

  /** @description Servicio de persistencia local SQLite. */
  private readonly db = inject(DbHelperService);

  /** @description Bóveda RSA para encriptación en tránsito. */
  private readonly cryptoService = inject(CryptoService);

  /** @description URL base del endpoint de autenticación desde el entorno activo. */
  private readonly API_URL = environment.authUrl;

  /** Signal reactivo que expone el estado global del usuario logueado. */
  currentUser = signal<User | null>(null);

  /** Almacén en memoria RAM para el JSON Web Token de la sesión. */
  private accessToken: string | null = null;

  /**
   * @method getToken
   * Recupera el token JWT de la memoria volátil.
   * @returns {string | null} El token de acceso o null si no hay sesión.
   */
  getToken(): string | null {
    return this.accessToken;
  }

  /**
   * @method setToken
   * Inyecta manualmente un token en la memoria RAM (usado por interceptores).
   * @param {string} token - El token JWT a almacenar.
   * @returns {void}
   */
  setToken(token: string): void {
    this.accessToken = token;
  }

  /**
   * @method register
   * @description Envía los datos de un nuevo prospecto al backend para su creación.
   * @param {Partial<User>} userData - Objeto con los datos del formulario de registro.
   * @returns {Promise<User>} Observable convertido a promesa con los datos del usuario creado.
   */
  async register(userData: Partial<User>): Promise<User> {
    const payload = { ...userData };
    if (payload.password) {
      payload.password = await this.cryptoService.encryptRSA(payload.password);
    }
    return firstValueFrom(
      this.http.post<User>(`${this.API_URL}/register`, payload)
    );
  }

  /**
   * @method login
   * @description Autentica las credenciales y establece la sesión en RAM y/o SQLite.
   * @param {string} id - ID del usuario (correo / username).
   * @param {string} pass - Contraseña en texto plano.
   * @param {boolean} [remember=false] - Define si se guarda la sesión en base de datos local.
   * @returns {Promise<AuthResponse>} Respuesta con el JWT y el perfil del usuario.
   * @throws {Error} Si el servidor no retorna un access_token válido.
   */
  async login(
    id: string,
    pass: string,
    remember: boolean = false
  ): Promise<AuthResponse> {
    const encryptedPass = await this.cryptoService.encryptRSA(pass);
    const response = await firstValueFrom(
      this.http.post<AuthResponse>(`${this.API_URL}/login`, {
        identifier: id,
        password: encryptedPass,
      })
    );

    if (response?.access_token) {
      this.accessToken = response.access_token;
      this.currentUser.set(response.user);
      if (remember)
        await this.db.saveSession(response.access_token, response.user);
      return response;
    }
    throw new Error('Fallo en la autenticación: Token no recibido.');
  }

  /**
   * @method forgotPassword
   * @description Fase 1: Solicita al servidor el envío del código OTP de 6 dígitos.
   * @param {string} email - Correo del usuario que desea recuperar acceso.
   * @returns {Promise<{ success: boolean }>} Confirmación del inicio del proceso.
   */
  async forgotPassword(email: string): Promise<{ success: boolean }> {
    return firstValueFrom(
      this.http.post<{ success: boolean }>(`${this.API_URL}/forgot-password`, {
        email,
      })
    );
  }

  /**
   * @method verifyOtp
   * @description Fase 2: Valida el OTP y obtiene el token firmado para el cambio de clave.
   * @param {string} email - Correo del usuario.
   * @param {string} otp - Código numérico de 6 dígitos.
   * @returns {Promise<{ recoveryToken: string }>} Token JWT efímero de autorización.
   */
  async verifyOtp(
    email: string,
    otp: string
  ): Promise<{ recoveryToken: string }> {
    return firstValueFrom(
      this.http.post<{ recoveryToken: string }>(`${this.API_URL}/verify-otp`, {
        email,
        otp,
      })
    );
  }

  /**
   * @method resetPassword
   * @description Fase 3: Ejecuta la actualización definitiva de la contraseña.
   * @param {string} email - Correo asociado.
   * @param {string} pass - Nueva contraseña segura.
   * @param {string} token - Token de recuperación obtenido en la fase 2.
   * @returns {Promise<{ message: string }>} Mensaje de éxito del servidor.
   */
  async resetPassword(
    email: string,
    pass: string,
    token: string
  ): Promise<{ message: string }> {
    const encryptedPass = await this.cryptoService.encryptRSA(pass);
    return firstValueFrom(
      this.http.post<{ message: string }>(`${this.API_URL}/reset-password`, {
        email,
        password: encryptedPass,
        recoveryToken: token,
      })
    );
  }

  /**
   * @method logout
   * @description Cierra la sesión activa borrando huellas en RAM y persistencia local.
   * @returns {Promise<void>}
   */
  async logout(): Promise<void> {
    this.accessToken = null;
    this.currentUser.set(null);
    await this.db.clearSession();
  }
}

import { inject, Injectable, NgZone } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { DbHelperService } from './db-helper.service';
import { CapacitorSQLite, JsonSQLite } from '@capacitor-community/sqlite'; // fix: _JsonSQLite → JsonSQLite
import { firstValueFrom } from 'rxjs';
import { BIRD_DATABASE_SCHEMA } from '../db/init-queries';
import { logger } from '../utils/logger';

/**
 * @sdd
 * [Objetivo]: Importar el catálogo inicial de aves desde un JSON maestro a SQLite.
 * Optimizado con NgZone para evitar el crash de memoria RAM en Angular.
 * [I/O]: Depende de HttpClient, DbHelperService, NgZone, CapacitorSQLite.
 * Expone: seedDatabase(): Promise<void>
 * [Edge Cases]: Si ya hay datos en la DB, omite la importación. Si falla, notifica
 * seedingComplete para no bloquear la app.
 */
@Injectable({ providedIn: 'root' })
export class BirdSeederService {
  private readonly DB_NAME = 'aviturismo_local_v2';
  private readonly http = inject(HttpClient);
  private readonly db = inject(DbHelperService);
  private readonly zone = inject(NgZone);

  /**
   * @method seedDatabase
   * @description Verifica si existen datos y, de no ser así, descarga e inyecta el JSON original.
   * @returns {Promise<void>}
   */
  async seedDatabase(): Promise<void> {
    try {
      // 1. Verificación: Si ya hay aves, no hacemos nada y marcamos como listo.
      const data = await this.db.query('SELECT id FROM birds LIMIT 1');
      if (data.length > 0) {
        logger.debug(
          '🆗 [Seeder] La base de datos ya contiene información. Omitiendo importación.'
        );
        this.db.setSeedingComplete();
        return;
      }

      logger.debug('📥 [Seeder] Iniciando descarga del JSON maestro...');

      const jsonContent = await firstValueFrom(
        this.http.get('assets/db/db-aves.json')
      );

      logger.debug(
        '⚙️ [Seeder] Procesando importación de SQLite fuera de Angular (Optimizando RAM)...'
      );

      // Ejecución segura fuera del ciclo de detección de Angular para evitar el Crash de memoria.
      await this.zone.runOutsideAngular(async () => {
        // Forzamos que el JSON inyecte los datos en la base de datos correcta (v2)
        // ya que el JSON original viene hardcodeado con 'aviturismo_local'.
        (jsonContent as { database?: string }).database = this.DB_NAME;

        // --- IMPORTANTE: CERRAR CONEXIÓN ANTES DEL IMPORT ---
        // Esto evita que CapacitorSQLite sobrescriba el archivo virtual WASM
        // y luego la conexión activa lo vuelva a sobrescribir vacío.
        await this.db.closeActiveConnection();

        // Envolvemos el objeto en JSON.stringify, que es exactamente lo que el plugin exige
        await CapacitorSQLite.importFromJson({
          jsonstring: JSON.stringify(jsonContent),
        });

        // --- REABRIR CONEXIÓN PARA CONTINUAR ---
        await this.db.openActiveConnection();

        // Protección de Sesión: Como el modo "full" del JSON borra todo, recreamos la tabla técnica.
        await this.db.execute(`
          CREATE TABLE IF NOT EXISTS session (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token TEXT NOT NULL,
            user_data TEXT NOT NULL
          );
        `);

        // Ejecutar todo el esquema para asegurar que existan las tablas que no vienen en el JSON
        for (const query of BIRD_DATABASE_SCHEMA) {
          try {
            await this.db.execute(query);
          } catch(e: unknown) {
            // Silenciar advertencias de migraciones ya aplicadas para mantener limpia la consola
            if (!String(e).includes('duplicate column name')) {
              logger.warn('[Seeder] Migration/Query skipped:', e);
            }
          }
        }

        // Persistencia obligatoria tras una carga masiva.
        await this.db.saveToStore();
      });

      // Recargamos la conexión en memoria para que IndexedDB hidrate el RAM
      await this.db.reloadConnection();

      logger.debug(
        '✅ [Seeder] Catálogo poblado con éxito desde el archivo maestro.'
      );

      // Notificamos al sistema que ya se pueden consultar aves.
      this.db.setSeedingComplete();
    } catch (error) {
      logger.error('❌ [Seeder] Error crítico durante el poblado:', error);
      // Evitamos un bloqueo permanente de la app en caso de fallo catastrófico
      this.db.setSeedingComplete();
    }
  }
}

// Supresión de exportación muerta del tipo no utilizado directamente
export type { JsonSQLite };

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { JSEncrypt } from 'jsencrypt';
import { logger } from '../utils/logger';
import { environment } from '../../../environments/environment';

/**
 * @sdd
 * [Objetivo]: Bóveda asimétrica RSA en el lado del cliente. Obtiene la llave pública
 * del backend y encripta datos sensibles antes de transmitirlos.
 * [I/O]: Depende de HttpClient. Expone: encryptRSA(plainText), getPublicKey().
 * [Edge Cases]: Caché en memoria para evitar peticiones redundantes al endpoint /public-key.
 * Si la encriptación falla, retorna el texto plano como fallback silencioso.
 */
@Injectable({
  providedIn: 'root',
})
export class CryptoService {
  private readonly http = inject(HttpClient);
  private readonly API_URL = environment.authUrl;
  private publicKey: string | null = null;

  /**
   * @method getPublicKey
   * @description Obtiene la llave pública RSA del backend.
   * Utiliza caché en memoria para evitar peticiones redundantes.
   * @returns {Promise<string>} Llave pública en formato PEM.
   */
  async getPublicKey(): Promise<string> {
    if (this.publicKey) return this.publicKey;

    try {
      const response = await firstValueFrom(
        this.http.get<{ publicKey: string }>(`${this.API_URL}/public-key`)
      );
      this.publicKey = response.publicKey;
      return this.publicKey;
    } catch (error) {
      logger.error('Error al obtener la llave pública RSA', error);
      throw error;
    }
  }

  /**
   * @method encryptRSA
   * @description Encripta un texto plano usando RSA (PKCS1 v1.5).
   * @param {string} plainText - Texto a encriptar (ej. contraseña).
   * @returns {Promise<string>} Texto encriptado en Base64 o texto original si falla.
   */
  async encryptRSA(plainText: string): Promise<string> {
    try {
      const pubKey = await this.getPublicKey();
      const encryptor = new JSEncrypt();
      encryptor.setPublicKey(pubKey);
      const encrypted = encryptor.encrypt(plainText);
      return encrypted || plainText;
    } catch (_error) {
      logger.warn('Fallo en la encriptación RSA. Enviando en crudo como fallback.');
      return plainText;
    }
  }
}

import { Injectable } from '@angular/core';
import {
  CapacitorSQLite,
  SQLiteConnection,
  SQLiteDBConnection,
} from '@capacitor-community/sqlite';
import { Capacitor } from '@capacitor/core';
import { User } from '../models/auth.models';
import { BIRD_DATABASE_SCHEMA } from '../db/init-queries';
import { logger } from '../utils/logger';

/**
 * @interface SessionRecord
 * @description Estructura de persistencia para la sesión de usuario (R5).
 */
export interface SessionRecord {
  token: string;
  user_data: string | User;
}

/**
 * @class DbHelperService
 * @description Gestor central de infraestructura SQLite. Implementa persistencia dual y estado de preparación (R2).
 */
@Injectable({
  providedIn: 'root',
})
export class DbHelperService {
  /** Nombre de la DB sincronizado estrictamente con el JSON de aves */
  private readonly DB_NAME = 'aviturismo_local_v2';

  private readonly sqlite: SQLiteConnection = new SQLiteConnection(CapacitorSQLite);
  private db: SQLiteDBConnection | null = null;

  /** @description Bandera que indica si la conexión base está lista */
  private isDbReady: boolean = false;

  /** Bandera que indica si el Seeder ha terminado su trabajo */
  private isSeedingComplete: boolean = false;

  constructor() {}

  /**
   * @method saveToStore
   * @description Sincroniza la base de datos de la memoria RAM al almacenamiento IndexedDB (Web).
   * @returns {Promise<void>}
   */
  async saveToStore(): Promise<void> {
    try {
      await this.sqlite.saveToStore(this.DB_NAME);
      logger.debug('💾 [DbHelper] Cambios guardados físicamente en el disco (IndexedDB).');
    } catch (err) {
      logger.error('❌ [DbHelper] Error persistiendo en store:', err);
    }
  }

  /**
   * @method initDatabase
   * @description Orquestador de conexión inicial. Solo crea la conexión y la tabla de sesión.
   * @returns {Promise<void>}
   */

  async initDatabase(): Promise<void> {
    if (this.isDbReady) return;
    const platform = Capacitor.getPlatform();

    try {
      if (platform === 'web') {
        logger.debug('🌐 [DbHelper] Sincronizando con motor Web...');
        await this.waitForJeepSqlite();
        logger.debug('📦 [DbHelper] Inicializando Web Store de WASM...');
        await this.sqlite.initWebStore();
      }

      logger.debug('🔌 [DbHelper] Conectando a SQLite...');
      this.db = await this.sqlite.createConnection(
        this.DB_NAME,
        false,
        'no-encryption',
        1,
        false
      );

      if (this.db) {
        await this.db.open();

        // Tabla técnica requerida para la sesión
        await this.db.execute(`
          CREATE TABLE IF NOT EXISTS session (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token TEXT NOT NULL,
            user_data TEXT NOT NULL
          );
        `);

        // Parche de actualización para la tabla routes: añadir columna status si no existe
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN status TEXT DEFAULT 'DRAFT'`, []);
        } catch (_e) {
          // Ignorar si la columna ya existe
        }
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN department_id INTEGER`, []);
        } catch (_e) {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN municipality_id INTEGER`, []);
        } catch (_e) {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN name TEXT`, []);
        } catch (_e) {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN comments TEXT`, []);
        } catch (_e) {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN user_id TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN sql_deleted BOOLEAN DEFAULT 0`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE routes ADD COLUMN last_modified INTEGER DEFAULT (strftime('%s', 'now'))`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE route_sightings ADD COLUMN sql_deleted BOOLEAN DEFAULT 0`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE route_sightings ADD COLUMN last_modified INTEGER DEFAULT (strftime('%s', 'now'))`, []);
        } catch {}
        try {
          await this.db.execute(`
            DELETE FROM route_sightings WHERE route_id IN (SELECT id FROM routes WHERE sync_status = 'synced');
            DELETE FROM routes WHERE sync_status = 'synced';
          `);
        } catch {}

        // Parche de actualización para la tabla sites: añadir campos de negocio / contacto
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN municipality TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN cover_url TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN logo_url TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN contact_phone TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN contact_whatsapp TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN website TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN instagram TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN facebook TEXT`, []);
        } catch {}
        try {
          await this.db.run(`ALTER TABLE sites ADD COLUMN has_bird_checklist BOOLEAN DEFAULT 0`, []);
        } catch {}

        // Ejecutar todo el esquema para asegurar que existan las tablas nuevas (offline-first)
        for (const query of BIRD_DATABASE_SCHEMA) {
          try {
            await this.db.execute(query);
          } catch(e: unknown) {
            if (!String(e).includes('duplicate column name')) {
              logger.warn('[DbHelper] Migration/Query skipped:', e);
            }
          }
        }

        this.isDbReady = true;
        logger.debug('✅ [DbHelper] Motor SQLite en línea y conectado a: ' + this.DB_NAME);
      }
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : 'Error desconocido';
      logger.error('❌ [DbHelper] ERROR de inicialización:', msg);
      this.isDbReady = false;
      throw error;
    }
  }

  /**
   * @method closeActiveConnection
   * Cierra la conexión activa a la base de datos local.
   */
  async closeActiveConnection(): Promise<void> {
    try {
      if (this.db) {
        await this.sqlite.closeConnection(this.DB_NAME, false);
        logger.debug('✅ [DbHelper] Conexión cerrada preventivamente.');
      }
    } catch (e) {
      logger.warn('⚠️ [DbHelper] Advertencia al cerrar conexión:', e);
    }
  }

  /**
   * @method openActiveConnection
   * Abre/recrea la conexión a la base de datos local.
   */
  async openActiveConnection(): Promise<void> {
    try {
      this.db = await this.sqlite.createConnection(this.DB_NAME, false, 'no-encryption', 1, false);
      await this.db.open();
      logger.debug('✅ [DbHelper] Conexión abierta/recargada exitosamente.');
    } catch (e) {
      logger.error('❌ [DbHelper] Error abriendo conexión:', e);
    }
  }

  /**
   * @method reloadConnection
   * Cierra y reabre la conexión a la base de datos local.
   */
  async reloadConnection(): Promise<void> {
    logger.debug('🔄 [DbHelper] Recargando conexión a SQLite...');
    await this.closeActiveConnection();
    await this.openActiveConnection();
  }

  /**
   * @method setSeedingComplete
   * Método para que el Seeder notifique que la base de datos ya tiene todos los datos.
   */
  public setSeedingComplete(): void {
    this.isSeedingComplete = true;
    logger.debug('✅ ✅ ✅ [DbHelper] SISTEMA TOTALMENTE POBLADO Y LISTO PARA CONSULTAS');
  }

  /**
   * @method getSeedingStatus
   * Permite a otros servicios saber si pueden consultar datos de negocio de forma segura.
   * @returns {boolean}
   */
  public getSeedingStatus(): boolean {
    return this.isSeedingComplete;
  }

  /**
   * @method waitForJeepSqlite
   * Asegura que el Web Component del motor WASM esté hidratado en el DOM.
   * @private
   */
  private async waitForJeepSqlite(): Promise<void> {
    return new Promise((resolve) => {
      const interval = setInterval(async () => {
        type JeepSqliteEl = Element & { componentOnReady?: () => Promise<void> };
        const jeepEl = document.querySelector('jeep-sqlite') as JeepSqliteEl | null;
        if (jeepEl && typeof jeepEl.componentOnReady === 'function') {
          clearInterval(interval);
          await customElements.whenDefined('jeep-sqlite');
          await jeepEl.componentOnReady();
          logger.debug('🎯 [DbHelper] Motor Jeep-SQLite hidratado.');
          resolve();
        }
      }, 50);
    });
  }

  /**
   * @method query
   * Ejecuta consultas de selección (SELECT) de forma segura.
   * @param {string} sql
   * @param {unknown[]} params
   * @returns {Promise<unknown[]>}
   */
  async query<T = Record<string, unknown>>(sql: string, params: unknown[] = []): Promise<T[]> {
    if (!this.isDbReady || !this.db) return [];
    try {
      const res = await this.db.query(sql, params);
      return (res.values as T[]) || [];
    } catch (_e) {
      // Si la tabla no existe aún, devolvemos un arreglo vacío de forma silenciosa.
      return [];
    }
  }

  /**
   * @method execute
   * Ejecuta sentencias directas (INSERT, UPDATE, DELETE).
   * @param sql - Sentencia SQL a ejecutar
   */
  async execute(sql: string): Promise<void> {
    if (this.isDbReady && this.db) {
      await this.db.execute(sql);
    }
  }

  /**
   * @method run
   * Ejecuta sentencias con parámetros. Lanza error si la BD no está lista.
   */
  async run(sql: string, params: unknown[]): Promise<void> {
    if (!this.isDbReady || !this.db) {
      const errMsg = `[DbHelper] run() llamado antes de que la BD esté lista. SQL: ${sql.substring(0, 60)}`;
      logger.error(errMsg);
      throw new Error(errMsg);
    }
    try {
      await this.db.run(sql, params);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logger.error(`[DbHelper] Error ejecutando SQL: ${msg}\nSQL: ${sql}`);
      throw e;
    }
  }

  /**
   * @method exportDatabaseToJson
   * Extrae toda la BD local en formato JSON
   * @returns {Promise<string>}
   */
  async exportDatabaseToJson(): Promise<string> {
    if (!this.db) throw new Error('Database no conectada');
    const result = await this.db.exportToJson('full');
    return JSON.stringify(result.export);
  }

  /**
   * @method exportDatabaseToSQL
   * Extrae toda la BD local y la convierte en un dump de sentencias SQL
   * @returns {Promise<string>}
   */

  async exportDatabaseToSQL(): Promise<string> {
    if (!this.db) throw new Error('Database no conectada');
    const result = await this.db.exportToJson('full');
    const data = result.export;
    if (!data) throw new Error('No se pudo exportar la estructura');

    let sqlDump = `-- Dump de base de datos generado: ${new Date().toISOString()}\n`;
    sqlDump += `-- DB: ${data.database} v${data.version}\n\n`;

    if (data.tables) {
      for (const table of data.tables) {
        if (table.schema && table.schema.length > 0) {
          const cols = table.schema.map(c => `${c.column} ${c.value}`).join(', ');
          sqlDump += `CREATE TABLE IF NOT EXISTS ${table.name} (${cols});\n`;
        }
        if (table.values && table.values.length > 0) {
          for (const row of table.values) {
            const vals = row.map(v => {
              if (v === null) return 'NULL';
              if (typeof v === 'string') return `'${v.replace(/'/g, "''")}'`;
              return v;
            }).join(', ');
            sqlDump += `INSERT INTO ${table.name} VALUES (${vals});\n`;
          }
        }
        sqlDump += '\n';
      }
    }
    return sqlDump;
  }

  /**
   * @method exportDatabaseToSQLite
   * @description Extrae la base de datos binaria (.sqlite) directamente desde IndexedDB (en Web)
   * @returns {Promise<Blob>}
   */
  async exportDatabaseToSQLite(): Promise<Blob> {
    const platform = Capacitor.getPlatform();
    if (platform !== 'web') {
      throw new Error('Solo soportado en web por ahora. En móvil se exporta de otra forma.');
    }

    await this.saveToStore(); // Aseguramos que la DB en memoria baje al IndexedDB

    return new Promise((resolve, reject) => {
      const nombreBDReal = 'jeepSqliteStore';
      const tablaReal = 'databases';

      const request = window.indexedDB.open(nombreBDReal);

      request.onerror = () => reject(`Error abriendo IndexedDB ${nombreBDReal}`);

      request.onsuccess = (event: Event) => {
        const idb = (event.target as IDBOpenDBRequest).result;
        try {
          if (!idb.objectStoreNames.contains(tablaReal)) {
            reject(new Error(`La base de datos ${nombreBDReal} no tiene la tabla ${tablaReal}.`));
            return;
          }

          const transaction = idb.transaction(tablaReal, 'readonly');
          const store = transaction.objectStore(tablaReal);
          const cursorRequest = store.openCursor();


          cursorRequest.onsuccess = (e: Event) => {
            const cursor = (e.target as IDBRequest<IDBCursorWithValue>).result;

            if (cursor) {
              const registroCompleto = cursor.value;
              let bytes: Uint8Array | null = null;

              if (registroCompleto instanceof Uint8Array) {
                bytes = registroCompleto;
              } else if (registroCompleto && typeof registroCompleto === 'object') {
                for (const propiedad in registroCompleto) {
                  if (registroCompleto[propiedad] instanceof Uint8Array) {
                    bytes = registroCompleto[propiedad];
                    break;
                  }
                }
              }

              if (bytes) {
                logger.debug(`[DbHelper] Procesando DB binaria: ${bytes.byteLength} bytes...`);
                const blob = new Blob([bytes as unknown as BlobPart], { type: 'application/vnd.sqlite3' });
                idb.close();
                resolve(blob);
              } else {
                cursor.continue(); // Seguir buscando en el siguiente registro por si acaso
              }
            } else {
              idb.close();
              reject(new Error('No se encontraron bytes válidos en la base de datos jeepSqliteStore.'));
            }
          };

          cursorRequest.onerror = () => reject('Error leyendo cursor de IndexedDB');
        } catch (error) {
          reject(error);
        }
      };
    });
  }

  // --- MÉTODOS DE SESIÓN (R1) ---

  /**
   * @method getSession
   * Obtiene la sesión activa desde localStorage o SQLite como fallback.
   * @returns {Promise<SessionRecord | null>}
   */
  async getSession(): Promise<SessionRecord | null> {
    const localData = localStorage.getItem('session');
    if (localData) return JSON.parse(localData);

    if (!this.isDbReady || !this.db) return null;

    const res = await this.query(`SELECT token, user_data FROM session LIMIT 1`);
    return res.length > 0 ? (res[0] as unknown as SessionRecord) : null;
  }

  /**
   * @method saveSession
   * Persiste la sesión en localStorage y SQLite.
   * @param {string} token - JWT Token
   * @param {User} userData - Datos del usuario autenticado
   */
  async saveSession(token: string, userData: User): Promise<void> {
    const dataStr = typeof userData === 'string' ? userData : JSON.stringify(userData);
    localStorage.setItem('session', JSON.stringify({ token, user_data: dataStr }));

    if (this.isDbReady && this.db) {
      await this.db.execute(`DELETE FROM session`);
      await this.db.run(
        `INSERT INTO session (token, user_data) VALUES (?, ?)`,
        [token, dataStr]
      );
      await this.saveToStore();
    }
  }

  /**
   * @method clearSession
   * Elimina la sesión activa de todos los stores de persistencia.
   */
  async clearSession(): Promise<void> {
    localStorage.removeItem('session');
    if (this.isDbReady && this.db) {
      await this.db.execute(`DELETE FROM session`);
      try {
        await this.db.execute(`
          DELETE FROM route_sightings WHERE route_id IN (SELECT id FROM routes WHERE sync_status = 'synced');
          DELETE FROM routes WHERE sync_status = 'synced';
        `);
      } catch (_e) {}
      await this.saveToStore();
    }
  }
}

