const initialState: ActiveRouteState = {
  isTracking: false,
  currentRouteId: null,
  currentPath: [],
  totalDistance: 0,
  sightingsLog: [],
  startTime: null,
  endTime: null,
  departments: [],
  municipalities: [],
};

/**
 * @param coord1
 * @param coord2
 * @description Haversine formula to calculate the distance between two coordinates in km
 */
function calculateDistance(coord1: [number, number], coord2: [number, number]): number {
  const R = 6371; // Radius of the earth in km
  const dLat = (coord2[1] - coord1[1]) * (Math.PI / 180);
  const dLon = (coord2[0] - coord1[0]) * (Math.PI / 180);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(coord1[1] * (Math.PI / 180)) *
      Math.cos(coord2[1] * (Math.PI / 180)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

/**
 * @sdd
 * @description State management for the GPS tracking routes module using NgRx SignalStore.
 * @io Dispatches state to Dual-View UI and triggers SQLite persistence.
 */
export const ActiveRouteStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods(
    (
      store,
      db = inject(DbHelperService),
      geoService = inject(GeographyService),
      authService = inject(AuthService),
    ) => ({
      /**
       * Elemento documentado.
       * @param routeId
       */
      async startTracking(routeId: string) {
        const startIso = new Date().toISOString();
        patchState(store, {
          isTracking: true,
          currentRouteId: routeId,
          currentPath: [],
          totalDistance: 0,
          sightingsLog: [],
          startTime: startIso,
        });

        // Persist empty route skeleton immediately (FK anchor for sightings)
        logger.debug('[ActiveRouteStore] Iniciando ruta:', routeId);
        const currentUserId = authService.currentUser()?.id || null;
        await db.run(
          `INSERT INTO routes (id, user_id, start_time, total_km, duration_mins, sync_status, status) VALUES (?, ?, ?, 0.0, 0, ?, ?)`,
          [routeId, currentUserId, startIso, 'pending_sync', 'DRAFT'],
        );
        // CRITICAL on Web: flush in-memory WAL to IndexedDB
        await db.saveToStore();
        logger.debug('[ActiveRouteStore] Ruta esqueleto guardada y persistida en disco.');
      },

    /**
     * Elemento documentado.
     * @param routeId
     * @param isTracking
     */
    async loadRoute(routeId: string, isTracking: boolean) {
      logger.debug('[ActiveRouteStore] Cargando ruta existente:', routeId);
      const routes = await db.query('SELECT * FROM routes WHERE id = ?', [routeId]);
      if (!routes || routes.length === 0) return;
      const route = routes[0] as unknown as RouteEntity;

      let currentPath: [number, number][] = [];
      try {
        const pathGeoJson = route.path_geojson
          ? JSON.parse(route.path_geojson)
          : { coordinates: [] };
        currentPath = pathGeoJson.coordinates || [];
      } catch {
        // Ignorar error al parsear GeoJSON no formateado
      }

      const sightings =
        (await db.query(
          `
        SELECT rs.*, b.common_name, b.scientific_name, b.english_name, b.base_image 
        FROM route_sightings rs 
        LEFT JOIN birds b ON rs.bird_id = b.id 
        WHERE rs.route_id = ? ORDER BY rs.timestamp DESC
      `,
          [routeId],
        )) || [];

      const mappedSightings = (sightings as Record<string, string>[]).map(
        (s: Record<string, string>) => ({
          ...s,
          birdInfo: {
            common_name: s['common_name'],
            scientific_name: s['scientific_name'],
            english_name: s['english_name'],
            base_image: s['base_image'],
          },
        }),
      ) as unknown as (IRouteSighting & {
        /**
         * Información taxonómica y visual del ave asociada al avistamiento.
         */
        birdInfo?: Partial<IBirdSearch>;
      })[];

      let effectiveStartTime = route.start_time;
      let effectiveEndTime = route.end_time || null;

      if (isTracking && route.duration_mins) {
        // Ajustar el startTime para omitir el tiempo pausado
        const shiftedStartMs = Date.now() - route.duration_mins * 60000;
        effectiveStartTime = new Date(shiftedStartMs).toISOString();
        effectiveEndTime = null;
      } else if (isTracking) {
        effectiveEndTime = null;
      }

      patchState(store, {
        isTracking: isTracking,
        currentRouteId: routeId,
        currentPath: currentPath,
        totalDistance: route.total_km || 0,
        sightingsLog: mappedSightings,
        startTime: effectiveStartTime || null,
        endTime: effectiveEndTime,
      });

      return route;
    },

    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     */
    /**
     * Elemento documentado.
     * @param payload
     * @param payload.routeName
     * @param payload.routeType
     * @param payload.notes
     * @param payload.status
     * @param payload.departmentId
     * @param payload.municipalityId
     */
    async stopTracking(payload: {
      /**
       *
       */
      routeName: string;
      /**
       *
       */
      routeType: string;
      /**
       *
       */
      notes: string;
      /**
       *
       */
      status: 'DRAFT' | 'COMPLETED';
      /**
       *
       */
      departmentId?: number | null;
      /**
       *
       */
      municipalityId?: number | null;
    }) {
      const routeId = store.currentRouteId();
      if (!routeId) {
        logger.error('[ActiveRouteStore] stopTracking: No hay routeId activo. Abortando.');
        return;
      }

      const endTime = new Date().toISOString();
      const startIso = store.startTime();
      let durationMins = 0;
      if (startIso) {
        durationMins = Math.floor(
          (new Date(endTime).getTime() - new Date(startIso).getTime()) / 60000,
        );
      }
      const pathGeoJson = JSON.stringify({
        type: 'LineString',
        coordinates: store.currentPath() || [],
      });
      const safeDistance = Number(store.totalDistance()) || 0;

      logger.debug('[ActiveRouteStore] Guardando ruta:', routeId, 'status:', payload.status);

      await db.run(
        `UPDATE routes SET end_time = ?, route_type = ?, total_km = ?, duration_mins = ?, path_geojson = ?, name = ?, comments = ?, status = ?, department_id = ?, municipality_id = ? WHERE id = ?`,
        [
          endTime,
          payload.routeType || 'Desplazamiento',
          safeDistance,
          durationMins,
          pathGeoJson,
          payload.routeName || 'Ruta sin nombre',
          payload.notes || '',
          payload.status,
          payload.departmentId || null,
          payload.municipalityId || null,
          routeId,
        ],
      );

      // CRITICAL on Web: flush in-memory WAL to IndexedDB
      await db.saveToStore();
      logger.debug('[ActiveRouteStore] Ruta finalizada y persistida en disco correctamente.');

      patchState(store, {
        isTracking: false,
        currentRouteId: null,
        currentPath: [],
        totalDistance: 0,
        sightingsLog: [],
        startTime: null,
      });
    },

    /**
     * Cancela y limpia la sesión activa de tracking en memoria al descartar una ruta.
     */
    cancelTracking() {
      patchState(store, {
        isTracking: false,
        currentRouteId: null,
        currentPath: [],
        totalDistance: 0,
        sightingsLog: [],
        startTime: null,
      });
    },

    /**
     * @description RxJS Effect for tracking positions.
     * Uses `scan` to accumulate distance using Haversine formula without mutating global variables.
     */
    addPosition: rxMethod<[number, number]>(
      pipe(
        /**
         * Elemento documentado.
         */
        /**
         * Elemento documentado.
         */
        /**
         * Elemento documentado.
         */
        scan<[number, number], { /**
         *
         */
        coord: [number, number]; /**
         *
         */
        distance: number; /**
         *
         */
        isFirst: boolean }>(
          (acc, newCoord) => {
            if (acc.isFirst) {
              return { coord: newCoord, distance: 0, isFirst: false };
            }
            const dist = calculateDistance(acc.coord, newCoord);
            return { coord: newCoord, distance: dist, isFirst: false };
          },
          { coord: [0, 0], distance: 0, isFirst: true },
        ),
        tap(({ coord, distance }) => {
          patchState(store, (state) => ({
            currentPath: [...state.currentPath, coord],
            totalDistance: state.totalDistance + distance,
          }));
        }),
      ),
    ),

    /**
     * @param birdId
     * @param quantity
     * @param details
     * @param birdInfo
     * @description Adds a sighting log attached to the current GPS route.
     * Persists instantly to SQLite.
     */
    async addSighting(
      birdId: string,
      quantity: number = 1,
      details: string = '',
      birdInfo?: Partial<IBirdSearch>,
    ) {
      const routeId = store.currentRouteId();
      if (!routeId) return;

      const path = store.currentPath();
      // Si no hay fix GPS aún, usamos (0,0) para no perder el registro del avistamiento
      const lastCoord: [number, number] = path.length > 0 ? path[path.length - 1] : [0, 0];
      /**
       * Elemento documentado.
       */
      const newSighting: IRouteSighting & { /**
       *
       */
      birdInfo?: Partial<IBirdSearch> } = {
        id: crypto.randomUUID(),
        route_id: routeId,
        bird_id: birdId,
        lng: lastCoord[0],
        lat: lastCoord[1],
        timestamp: new Date().toISOString(),
        quantity,
        details,
        sync_status: 'pending_sync',
        birdInfo,
      };

      // 1. Update State
      patchState(store, (state) => {
        // Group similar sightings (as requested in SDD acceptance criteria)
        const existingIndex = state.sightingsLog.findIndex((s) => s.bird_id === birdId);
        if (existingIndex > -1) {
          const updatedLog = [...state.sightingsLog];
          updatedLog[existingIndex] = {
            ...updatedLog[existingIndex],
            quantity: updatedLog[existingIndex].quantity + quantity,
          };
          // Note: we might overwrite details or append them, let's keep it simple for now
          return { sightingsLog: updatedLog };
        }
        return { sightingsLog: [...state.sightingsLog, newSighting] };
      });

      // 2. Persist to SQLite
      const lat = Number(newSighting.lat) || 0.0;
      const lng = Number(newSighting.lng) || 0.0;
      const qty = Number(newSighting.quantity) || 1;

      await db.run(
        `INSERT INTO route_sightings (id, route_id, bird_id, lat, lng, timestamp, quantity, details, sync_status) 
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET quantity = quantity + ?`,
        [
          newSighting.id,
          newSighting.route_id,
          newSighting.bird_id,
          lat,
          lng,
          newSighting.timestamp,
          qty,
          newSighting.details || '',
          newSighting.sync_status || 'pending_sync',
          qty,
        ],
      );
    },

    /**
     * Elemento documentado.
     */
    async loadDepartments(): Promise<void> {
      try {
        const depts = await geoService.getDepartments();
        patchState(store, { departments: depts });
      } catch (err) {
        logger.error('Error loading departments in ActiveRouteStore', err);
      }
    },

    /**
     * Elemento documentado.
     * @param departmentId
     */
    async loadMunicipalities(departmentId: number): Promise<void> {
      try {
        const munis = await geoService.getMunicipalities(departmentId);
        patchState(store, { municipalities: munis });
      } catch (err) {
        logger.error('Error loading municipalities in ActiveRouteStore', err);
      }
    },
  })),
);

import { inject } from '@angular/core';
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { AuthService } from '../services/auth.service';
import { FeedStore } from './feed.store';
import { User, AuthResponse } from '../models/auth.models';

/**
 * Elemento documentado.
 */
export type AuthState = {
  /**
   * Elemento documentado.
   */
  user: User | null;
  /**
   * Elemento documentado.
   */
  accessToken: string | null;
  /**
   * Elemento documentado.
   */
  isLoading: boolean;
};

const initialState: AuthState = {
  user: null,
  accessToken: null,
  isLoading: false,
};

/**
 * @class AuthStore
 * @description Almacén centralizado y reactivo para la sesión usando NgRx SignalStore.
 */
export const AuthStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods((
    store,
    authService = inject(AuthService),
    feedStore = inject(FeedStore),
  ) => ({
    /**
     * Elemento documentado.
     * @param identifier
     * @param pass
     * @param remember
     */
    async login(
      identifier: string,
      pass: string,
      remember: boolean = false,
    ): Promise<AuthResponse> {
      patchState(store, { isLoading: true });
      try {
        const response = await authService.login(identifier, pass, remember);
        patchState(store, {
          user: response.user,
          accessToken: response.access_token,
          isLoading: false,
        });
        return response;
      } catch (err) {
        patchState(store, { isLoading: false });
        throw err;
      }
    },

    /**
     * Elemento documentado.
     * @param userData
     */
    async register(userData: Partial<User>): Promise<User> {
      patchState(store, { isLoading: true });
      try {
        const user = await authService.register(userData);
        patchState(store, { isLoading: false });
        return user;
      } catch (err) {
        patchState(store, { isLoading: false });
        throw err;
      }
    },

    /**
     * Elemento documentado.
     */
    async logout(): Promise<void> {
      patchState(store, { isLoading: true });
      await authService.logout();
      feedStore.resetFeed();
      patchState(store, { user: null, accessToken: null, isLoading: false });
    },

    /**
     * Elemento documentado.
     */
    syncFromService() {
      patchState(store, {
        user: authService.currentUser(),
        accessToken: authService.getToken(),
      });
    },
  })),
);

import { inject } from '@angular/core';
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { UserService } from '../services/user.service';
import { AuthService } from '../services/auth.service';
import { AuthStore } from './auth.store';
import { GeographyService } from '../services/geography.service';
import { User, UserMedalDto } from '../models/auth.models';

import { GeoLocation } from '../services/geography.service';
import { logger } from '../utils/logger';

/**
 *
 */
export type ProfileState = {
  /**
   *
   */
  viewedUser: User | null;
  /**
   *
   */
  medals: UserMedalDto[];
  /**
   *
   */
  isLoading: boolean;
  /**
   *
   */
  departments: GeoLocation[];
  /**
   *
   */
  municipalities: GeoLocation[];
};

const initialState: ProfileState = {
  viewedUser: null,
  medals: [],
  isLoading: false,
  departments: [],
  municipalities: [],
};

/**
 * @class ProfileStore
 * @description Almacén centralizado y reactivo para la gestión de perfil y seguridad.
 * Encapsula los llamados HTTP del UserService para cumplir con el Principio de Responsabilidad Única.
 */
export const ProfileStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods(
    (
      store,
      userService = inject(UserService),
      authService = inject(AuthService),
      authStore = inject(AuthStore),
      geoService = inject(GeographyService),
    ) => ({
      /**
       * Carga el perfil del usuario autenticado o de un usuario externo por ID.
       * @param id Identificador opcional del usuario.
       * @returns Promesa con los datos del usuario o null.
       */
      async loadProfile(id?: string | null): Promise<User | null> {
        patchState(store, { isLoading: true });
        try {
          const user = id ? await userService.getProfileById(id) : await userService.getProfile();

          patchState(store, { viewedUser: user, isLoading: false });

          // Si es el perfil propio, actualizamos el state global de Auth
          if (!id || (authService.currentUser() && id === authService.currentUser()?.id)) {
            authService.currentUser.set(user);
            authStore.syncFromService();
          }

          return user;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      /**
       * Actualiza los datos de perfil del usuario actual.
       * @param updateData Datos a actualizar.
       * @returns Promesa con el usuario actualizado.
       */
      async updateProfile(updateData: Partial<User>): Promise<User> {
        patchState(store, { isLoading: true });
        try {
          const updatedUser = await userService.updateProfile(updateData);
          patchState(store, { viewedUser: updatedUser, isLoading: false });
          authService.currentUser.set(updatedUser);
          authStore.syncFromService();
          return updatedUser;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      /**
       *
       * @param data
       * @param data.oldPassword
       * @param data.newPassword
       */
      async updatePassword(data: {
        /**
         *
         */
        oldPassword?: string;
        /**
         *
         */
        newPassword?: string;
      }): Promise<{ /**
       *
       */
      message: string }> {
        patchState(store, { isLoading: true });
        try {
          const result = await userService.updatePassword(data);
          patchState(store, { isLoading: false });
          return result;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      /**
       *
       * @param file
       * @param type
       * @param extension
       */
      async uploadImage(file: Blob, type: 'AVATAR' | 'COVER', extension: string): Promise<string> {
        patchState(store, { isLoading: true });
        try {
          const uploadType = type === 'AVATAR' ? 'avatar' : 'cover';
          const { url } = await userService.uploadImage(file, uploadType, extension);

          const currentUser = store.viewedUser();
          if (currentUser) {
            const updated = {
              ...currentUser,
              [type === 'AVATAR' ? 'avatarUrl' : 'coverUrl']: url,
            };
            patchState(store, { viewedUser: updated });
            authService.currentUser.set(updated);
            authStore.syncFromService();
          }

          patchState(store, { isLoading: false });
          return url;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      /**
       *
       */
      async loadMedals(): Promise<UserMedalDto[]> {
        patchState(store, { isLoading: true });
        try {
          const medals = await userService.getMyMedals();
          patchState(store, { medals, isLoading: false });
          return medals;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      /**
       *
       */
      async loadDepartments(): Promise<void> {
        try {
          const depts = await geoService.getDepartments();
          patchState(store, { departments: depts });
        } catch (err) {
          logger.error('Error loading departments', err);
        }
      },

      /**
       *
       * @param departmentId
       */
      async loadMunicipalities(departmentId: number): Promise<void> {
        try {
          const munis = await geoService.getMunicipalities(departmentId);
          patchState(store, { municipalities: munis });
        } catch (err) {
          logger.error('Error loading municipalities', err);
        }
      },
    }),
  ),
);

/**
 * @sdd
 * @description Motor de Sincronización Base (Sync Queue Service) usando NgRx SignalStore.
 * @io Injects DbHelperService (SQLite) and SyncService. Pushes local changes to the backend and pulls remote changes.
 * @edge_cases Maneja pérdida de red, resolución de conflictos basada en 'last_modified' y soft-deletes ('sql_deleted').
 */
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { inject } from '@angular/core';
import { DbHelperService } from '../services/db-helper.service';
import { NetworkService } from '../services/network.service';
import { SyncService } from '../services/sync.service';
import { AuthService } from '../services/auth.service';
import { User } from '../models/auth.models';
import { logger } from '../utils/logger';

/**
 *
 */
export interface SyncState {
  /**
   *
   */
  isSyncing: boolean;
  /**
   *
   */
  lastSyncTimestamp: number;
  /**
   *
   */
  pendingChangesCount: number;
}

const initialState: SyncState = {
  isSyncing: false,
  lastSyncTimestamp: Number(localStorage.getItem('lastSyncTimestamp') || 0),
  pendingChangesCount: 0,
};

export const SyncQueueStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods(
    (
      store,
      db = inject(DbHelperService),
      syncService = inject(SyncService),
      network = inject(NetworkService),
      authService = inject(AuthService),
    ) => ({
      /**
       * Calcula la cantidad de avistamientos locales pendientes de sincronizar
       */
      async calculatePendingChanges() {
        try {
          const result = await db.query(
            `SELECT COUNT(*) as count FROM sightings WHERE last_modified > ?`,
            [store.lastSyncTimestamp()],
          );
          const count = Number(result[0]?.['count']) || 0;
          patchState(store, { pendingChangesCount: count });
        } catch (error) {
          logger.error('Error calculando cambios pendientes', error);
        }
      },

      /**
       * Inicia el proceso de sincronización con el backend (Push local -> Pull remoto)
       * @param force Ignora el intervalo de 5 minutos si es true
       */
      async executeSyncCycle(force: boolean = false) {
        if (store.isSyncing() || !network.isOnline()) {
          logger.warn('Sync omitido: Offline o ya en progreso.');
          return;
        }

        const now = Math.floor(Date.now() / 1000);
        const SYNC_INTERVAL = 5 * 60; // 5 minutos en segundos
        if (!force && now - store.lastSyncTimestamp() < SYNC_INTERVAL) {
          logger.debug(`Sync omitido: Han pasado menos de 5 minutos desde el último sync.`);
          return;
        }

        patchState(store, { isSyncing: true });

        try {
          // 1. PUSH: Enviar cambios locales al backend para el usuario actual
          const currentUserId = authService.currentUser()?.id;
          const pendingRoutes = currentUserId
            ? (((await db.query(
                `SELECT * FROM routes WHERE sync_status = 'pending_sync' AND status = 'COMPLETED' AND user_id = ?`,
                [currentUserId],
              )) || []) as Record<string, unknown>[])
            : [];

          const routesWithPendingSightings = currentUserId
            ? (((await db.query(
                `SELECT DISTINCT r.* FROM routes r
                 INNER JOIN route_sightings rs ON rs.route_id = r.id
                 WHERE rs.sync_status = 'pending_sync' AND r.status = 'COMPLETED' AND r.user_id = ?`,
                [currentUserId],
              )) || []) as Record<string, unknown>[])
            : [];

          const routeMap = new Map<string, Record<string, unknown>>();
          for (const r of [...pendingRoutes, ...routesWithPendingSightings]) {
            if (r['id']) {
              routeMap.set(String(r['id']), r);
            }
          }
          const routesToSync = Array.from(routeMap.values());

          // Cargar sesión para perfíles PENDING
          const session = await db.getSession();
          const pendingUsers: User[] = [];
          if (session && session.user_data) {
            const rawUser = session.user_data as unknown;
            const uObj =
              typeof rawUser === 'string'
                ? (JSON.parse(rawUser) as User)
                : (rawUser as User);
            const userRecord = uObj as unknown as Record<string, unknown>;
            if (userRecord['sync_status'] === 'PENDING') {
              pendingUsers.push(uObj);
            }
          }

          if (routesToSync.length > 0 || pendingUsers.length > 0) {
            const nestedRoutes: Record<string, unknown>[] = [];
            const syncedSightingIds: string[] = [];

            for (const route of routesToSync) {
              const routeId = String(route['id']);
              const sightings =
                ((await db.query(
                  `SELECT * FROM route_sightings WHERE route_id = ?`,
                  [routeId],
                )) || []) as Record<string, unknown>[];

              for (const s of sightings) {
                if (s['id']) {
                  syncedSightingIds.push(String(s['id']));
                }
              }

              nestedRoutes.push({
                ...route,
                sightings,
              });
            }

            const bulkPayload = { routes: nestedRoutes, users: pendingUsers };
            await syncService.pushChanges(bulkPayload).toPromise();

            // Una vez confirmada la subida a Postgres, limpiar de SQLite local (la BD local solo contiene datos offline)
            for (const route of routesToSync) {
              const rId = route['id'];
              try {
                await db.run(`DELETE FROM route_sightings WHERE route_id = ?`, [rId]);
                await db.run(`DELETE FROM routes WHERE id = ?`, [rId]);
              } catch (cleanErr) {
                logger.warn('[SyncQueue] Advertencia limpiando ruta en SQLite, marcando synced:', cleanErr);
                await db.run(`UPDATE routes SET sync_status = 'synced' WHERE id = ?`, [rId]);
              }
            }

            for (const sid of syncedSightingIds) {
              try {
                await db.run(`DELETE FROM route_sightings WHERE id = ?`, [sid]);
              } catch {
                await db.run(`UPDATE route_sightings SET sync_status = 'synced' WHERE id = ?`, [sid]);
              }
            }
            await db.saveToStore();

            if (pendingUsers.length > 0 && session) {
              const uObj = pendingUsers[0];
              (uObj as unknown as Record<string, unknown>)['sync_status'] = 'SYNCED';
              await db.saveSession(session.token, uObj);
            }
          }

          // 2. PULL: Recibir catálogos del backend
          const remoteCatalogs = await syncService
            .pullCatalogs(store.lastSyncTimestamp())
            .toPromise();

          if (remoteCatalogs) {
            // Upsert lógico para Guías
            if (remoteCatalogs.guides && remoteCatalogs.guides.length > 0) {
              for (const guide of remoteCatalogs.guides) {
                await db.query(
                  `INSERT INTO guides (id, full_name, location, specialty, rating, photo_url, details, languages, bio, phone, last_modified, sql_deleted) 
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                      ON CONFLICT(id) DO UPDATE SET
                      full_name=excluded.full_name, location=excluded.location, specialty=excluded.specialty,
                      rating=excluded.rating, photo_url=excluded.photo_url, details=excluded.details,
                      languages=excluded.languages, bio=excluded.bio, phone=excluded.phone,
                      last_modified=excluded.last_modified, sql_deleted=excluded.sql_deleted`,
                  [
                    guide.id,
                    guide.fullName,
                    guide.location,
                    guide.specialty,
                    guide.rating,
                    guide.photoUrl,
                    guide.details,
                    guide.languages,
                    guide.bio,
                    guide.phone,
                    guide.last_modified,
                    guide.sql_deleted ? 1 : 0,
                  ],
                );
              }
            }

            // Upsert lógico para Sitios
            if (remoteCatalogs.sites && remoteCatalogs.sites.length > 0) {
              for (const site of remoteCatalogs.sites) {
                await db.query(
                  `INSERT INTO sites (id, name, department, municipality, rating, description, cover_url, logo_url, contact_phone, contact_whatsapp, website, instagram, facebook, has_bird_checklist, geo_lat, geo_lng, route_json, last_modified, sql_deleted) 
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                      ON CONFLICT(id) DO UPDATE SET
                      name=excluded.name, department=excluded.department, municipality=excluded.municipality,
                      rating=excluded.rating, description=excluded.description,
                      cover_url=excluded.cover_url, logo_url=excluded.logo_url,
                      contact_phone=excluded.contact_phone, contact_whatsapp=excluded.contact_whatsapp,
                      website=excluded.website, instagram=excluded.instagram, facebook=excluded.facebook,
                      has_bird_checklist=excluded.has_bird_checklist,
                      geo_lat=excluded.geo_lat, geo_lng=excluded.geo_lng,
                      route_json=excluded.route_json,
                      last_modified=excluded.last_modified, sql_deleted=excluded.sql_deleted`,
                  [
                    site.id,
                    site.name,
                    site.department,
                    site.municipality || '',
                    site.rating,
                    site.description,
                    site.cover_url || '',
                    site.logo_url || '',
                    site.contact_phone || '',
                    site.contact_whatsapp || '',
                    site.website || '',
                    site.instagram || '',
                    site.facebook || '',
                    site.has_bird_checklist ? 1 : 0,
                    site.location?.lat ?? 0,
                    site.location?.lng ?? 0,
                    JSON.stringify(site.routeGeoJson),
                    site.last_modified,
                    site.sql_deleted ? 1 : 0,
                  ],
                );
              }
            }

            // Upsert lógico para Servicios de Sitios
            if (remoteCatalogs.site_services && remoteCatalogs.site_services.length > 0) {
              for (const service of remoteCatalogs.site_services) {
                await db.query(
                  `INSERT INTO site_services (id, site_id, type, name, description, photo_url, price, last_modified, sql_deleted) 
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                      ON CONFLICT(id) DO UPDATE SET
                      site_id=excluded.site_id, type=excluded.type, name=excluded.name,
                      description=excluded.description, photo_url=excluded.photo_url, price=excluded.price,
                      last_modified=excluded.last_modified, sql_deleted=excluded.sql_deleted`,
                  [
                    service.id,
                    service.site_id,
                    service.type,
                    service.name,
                    service.description,
                    service.photoUrl,
                    service.price,
                    service.last_modified,
                    service.sql_deleted ? 1 : 0,
                  ],
                );
              }
            }

            // Upsert para Site Birds (Opcional, relación)
            if (remoteCatalogs.site_birds && remoteCatalogs.site_birds.length > 0) {
              for (const sb of remoteCatalogs.site_birds) {
                await db.query(
                  `INSERT OR IGNORE INTO site_birds (site_id, bird_id) VALUES (?, ?)`,
                  [sb.site_id, sb.bird_id],
                );
              }
            }

            // Upsert Geografía
            if (remoteCatalogs.departments && remoteCatalogs.departments.length > 0) {
              for (const dep of remoteCatalogs.departments) {
                await db.query(
                  `INSERT OR REPLACE INTO departments (id, name, sql_deleted) VALUES (?, ?, ?)`,
                  [dep.id, dep.name, dep.sql_deleted ? 1 : 0],
                );
              }
            }

            if (remoteCatalogs.municipalities && remoteCatalogs.municipalities.length > 0) {
              for (const mun of remoteCatalogs.municipalities) {
                await db.query(
                  `INSERT OR REPLACE INTO municipalities (id, department_id, name, sql_deleted) VALUES (?, ?, ?, ?)`,
                  [mun.id, mun.department_id, mun.name, mun.sql_deleted ? 1 : 0],
                );
              }
            }

            // Upsert Aves (El catálogo maestro vital)
            if (remoteCatalogs.birds && remoteCatalogs.birds.length > 0) {
              for (const bird of remoteCatalogs.birds) {
                await db.query(
                  `INSERT OR REPLACE INTO birds (id, scientific_name, english_name, common_name, min_altitude, max_altitude, viewing_difficulty, size, environment, behavior, colors, authority, gbif_link, wikiaves_link, ebird_link, other_sources, base_image, image_copyright, habitat_id, conservation_status_id, family_id, residency_type_id, feeding_type_id, beak_morphology_id, wing_morphology_id, tail_morphology_id, leg_morphology_id, additional_info_id, sql_deleted, last_modified) 
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
                  [
                    bird.id,
                    bird.scientific_name,
                    bird.english_name,
                    bird.common_name,
                    bird.min_altitude,
                    bird.max_altitude,
                    bird.viewing_difficulty,
                    bird.size,
                    bird.environment,
                    bird.behavior,
                    bird.colors,
                    bird.authority,
                    bird.gbif_link,
                    bird.wikiaves_link,
                    bird.ebird_link,
                    bird.other_sources,
                    bird.base_image,
                    bird.image_copyright,
                    bird.habitat_id,
                    bird.conservation_status_id,
                    bird.family_id,
                    bird.residency_type_id,
                    bird.feeding_type_id,
                    bird.beak_morphology_id,
                    bird.wing_morphology_id,
                    bird.tail_morphology_id,
                    bird.leg_morphology_id,
                    bird.additional_info_id,
                    bird.sql_deleted ? 1 : 0,
                    Math.floor(new Date(bird.last_modified).getTime() / 1000),
                  ],
                );
              }
            }
          }

          const newTimestamp = Math.floor(Date.now() / 1000);
          localStorage.setItem('lastSyncTimestamp', newTimestamp.toString());
          patchState(store, {
            isSyncing: false,
            lastSyncTimestamp: newTimestamp,
            pendingChangesCount: 0,
          });
        } catch (error) {
          logger.error('Error crítico durante el ciclo de sincronización', error);
          patchState(store, { isSyncing: false });
        }
      },
    }),
  ),
);

