/**
 * @class ProfilePage
 * @description Gestión de perfil de usuario en FlockApp.
 * Implementa geografía dependiente, validación de Instagram y modo visitante con Bio/Social.
 */
@Component({
  selector: 'app-profile',
  templateUrl: './profile.page.html',
  styleUrls: ['./profile.page.scss'],
  standalone: true,
  imports: [
    IonHeader, IonToolbar, IonButtons,
    IonContent, IonIcon,
    IonButton, IonMenuButton, IonSelect, IonSelectOption,
    IonChip, IonLabel,
    CommonModule,
    FormsModule,
    AuthInputComponent,
    StatWidgetComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ProfilePage implements OnInit {
  private readonly userService = inject(UserService);
  private readonly geoService = inject(GeographyService);
  private readonly route = inject(ActivatedRoute);
  public readonly authService = inject(AuthService);
  private readonly ui = inject(UiService);
  private readonly modalCtrl = inject(ModalController);
  private readonly actionSheetCtrl = inject(ActionSheetController);
  private readonly db = inject(DbHelperService);

  /** @description Datos del usuario en vista */
  public viewedUser = signal<User | null>(null);
  public isLoading = signal<boolean>(true);
  
  public firstName = signal<string>('');
  public lastName = signal<string>('');
  public username = signal<string>('');
  public department = signal<string>('');
  public municipality = signal<string>('');
  public instagram = signal<string>('');
  public bio = signal<string>('');

  public isPristine = signal<boolean>(true);

  /** @description Listado de departamentos */
  public departments = signal<GeoLocation[]>([]);
  /** @description Listado de municipios del departamento seleccionado */
  public municipalities = signal<GeoLocation[]>([]);

  /** @description URL base del backend para activos estáticos */
  private readonly BASE_URL = 'http://localhost:3000';

  /** @description Computado para determinar propiedad del perfil */
  public isOwnProfile = computed(() => {
    const viewed = this.viewedUser();
    const current = this.authService.currentUser();
    return viewed && current ? viewed.id === current.id : false;
  });

  /** @description Estadísticas de actividad */
  public stats = signal<UserStats>({
    speciesCount: 0,
    sightingsCount: 0,
    medalsCount: 0,
    daysInApp: 0,
    natureTimeMinutes: 0,
  });

  constructor() {
    addIcons({
      atOutline,
      cameraOutline,
      checkmarkOutline,
      imageOutline,
      locationOutline,
      logoInstagram,
      bookOutline,
      trophyOutline,
      binocularsOutline,
      businessOutline,
      eyeOutline,
      pawOutline,
      mailOutline,
      lockClosedOutline,
      chevronForwardOutline,
      calendarOutline,
      timeOutline,
      trashOutline,
      closeOutline,
    });
  }

  /**
   * @method ngOnInit
   * @description Inicialización de vista y precarga de geografía.
   */
  async ngOnInit(): Promise<void> {
    await this.loadDepartments();
    this.checkRouteAndLoad();
  }

  public onFieldChange() {
    this.isPristine.set(false);
  }

  /**
   * @method getImageUrl
   * @description Resuelve la URL absoluta para recursos multimedia.
   * @param {string | undefined} path - Ruta relativa.
   */
  public getImageUrl(path: string | undefined): string {
    if (!path) return '';
    return path.startsWith('http') ? path : `${this.BASE_URL}${path}`;
  }

  /**
   * @method loadDepartments
   * @description Carga la lista inicial de departamentos.
   */
  private async loadDepartments(): Promise<void> {
    try {
      const data = await this.geoService.getDepartments();
      this.departments.set(data);
    } catch {
      logger.error('Falla en carga de geografía');
    }
  }

  /**
   * @method onDepartmentChange
   * @description Maneja la selección de departamento para cargar municipios.
   * @param {CustomEvent<{ value: string }>} event - Evento de cambio de IonSelect.
   */
  async onDepartmentChange(event: CustomEvent<{ value: string }>): Promise<void> {
    const name = event.detail.value;
    const dept = this.departments().find((d) => d.name === name);
    if (dept) {
      const data = await this.geoService.getMunicipalities(dept.id);
      this.municipalities.set(data);
      this.municipality.set('');
      this.onFieldChange();
    }
  }
  /**
   * Carga datos de perfil y métricas en modo desconectado desde SQLite (solo rutas completadas).
   */
  private async loadOfflineProfileFallback(): Promise<void> {
    try {
      const session = await this.db.getSession();
      let uObj: User | null = null;
      if (session && session.user_data) {
        uObj =
          typeof session.user_data === 'string'
            ? (JSON.parse(session.user_data) as User)
            : (session.user_data as User);
        this.viewedUser.set(uObj);
        this.firstName.set(uObj.firstName || '');
        this.lastName.set(uObj.lastName || '');
        this.username.set(uObj.username || '');
      }
      const targetUserId = uObj?.id || this.authService.currentUser()?.id;
      if (!targetUserId) return;

      const localStatsResult = ((await this.db.query(
        `
        SELECT COUNT(DISTINCT rs.bird_id) AS local_species,
               COALESCE(SUM(rs.quantity), 0) AS local_birds
        FROM route_sightings rs
        INNER JOIN routes r ON rs.route_id = r.id
        WHERE r.user_id = ? AND r.status = 'COMPLETED'
      `,
        [targetUserId],
      )) || []) as Record<string, number | string>[];
      if (localStatsResult.length > 0) {
        const current = this.stats();
        this.stats.set({
          ...current,
          speciesCount:
            Number(localStatsResult[0]['local_species']) || current.speciesCount,
          sightingsCount:
            Number(localStatsResult[0]['local_birds']) || current.sightingsCount,
        });
      }
    } catch (offlineErr: unknown) {
      logger.error('Error en fallback offline de perfil:', offlineErr);
    }
  }

  /**
   * Determina el usuario a visualizar y carga su perfil con métricas consolidadas desde Postgres.
   */
  private async checkRouteAndLoad(): Promise<void> {
    const userId = this.route.snapshot.paramMap.get('id');
    try {
      const data = userId
        ? await this.userService.getProfileById(userId)
        : await this.userService.getProfile();
      if (data) {
        this.viewedUser.set(data);
        this.firstName.set(data.firstName || '');
        this.lastName.set(data.lastName || '');
        this.username.set(data.username || '');
        this.department.set(data.department || '');
        this.municipality.set(data.municipality || '');
        this.instagram.set(data.instagram || '');
        this.bio.set(data.bio || '');

        if (data.stats) {
          this.stats.set(data.stats);
        }

        if (data.department) {
          const dept = this.departments().find((d) => d.name === data.department);
          if (dept) {
            const munis = await this.geoService.getMunicipalities(dept.id);
            this.municipalities.set(munis);
          }
        }
      }
      this.isLoading.set(false);
    } catch {
      await this.loadOfflineProfileFallback();
      this.isLoading.set(false);
    }
  }

  /**
   * @method onUpdateProfile
   * @description Persiste los cambios de texto en el backend.
   */
  async onUpdateProfile(): Promise<void> {
    if (!this.isOwnProfile()) return;
    await this.ui.showLoading('Sincronizando...');
    try {
      const payload = {
        firstName: this.firstName(),
        lastName: this.lastName(),
        department: this.department(),
        municipality: this.municipality(),
        instagram: this.instagram(),
        bio: this.bio()
      };
      const updated = await this.userService.updateProfile(payload);
      this.authService.currentUser.set(updated);
      this.viewedUser.set(updated);
      await this.ui.dismissLoading();
      this.ui.showToast('Perfil actualizado', 'success');
      this.isPristine.set(true);
    } catch {
      await this.ui.dismissLoading();
    }
  }

  /**
   * @method goToSecurity
   * @description Navegación o apertura de controles para cambio de contraseña.
   */
  async goToSecurity() {
    if (!this.isOwnProfile()) return;

    const modal = await this.modalCtrl.create({
      component: ChangePasswordComponent,
      breakpoints: [0, 0.6, 1], // R2: Diseño responsive (Bottom Sheet)
      initialBreakpoint: 1,
    });
    return await modal.present();
  }

  /**
   * Abre el modal interactivo con el catálogo y estado de medallas.
   */
  async openMedalsModal(): Promise<void> {
    const modal = await this.modalCtrl.create({
      component: UserMedalsComponent,
      componentProps: {
        medalsList: this.viewedUser()?.medals,
        title: this.isOwnProfile() ? 'Tus Medallas' : 'Medallas del Usuario',
      },
      breakpoints: [0, 0.7, 1],
      initialBreakpoint: 1,
    });
    await modal.present();
  }

  /**
   * Retorna la etiqueta legible del rol de usuario en la UI.
   * @param role Rol del usuario.
   * @returns Etiqueta amigable para la interfaz.
   */
  public getRoleLabel(role?: string | null): string {
    if (!role) return '';
    switch (role.toUpperCase()) {
      case 'BOTH':
        return 'Pajarero / Proveedor';
      case 'PAJARERO':
        return 'Pajarero';
      case 'PROVEEDOR':
        return 'Proveedor';
      default:
        return role;
    }
  }

  /**
   * Abre un menú de opciones para subir o eliminar la foto seleccionada.
   * @param type Tipo de recurso ('AVATAR' o 'COVER').
   */
  async changePhoto(type: 'AVATAR' | 'COVER'): Promise<void> {
    if (!this.isOwnProfile()) return;

    const hasCurrentPhoto =
      type === 'AVATAR'
        ? !!this.viewedUser()?.avatarUrl
        : !!this.viewedUser()?.coverUrl;
    const label = type === 'AVATAR' ? 'foto de perfil' : 'foto de portada';

    const buttons: ActionSheetButton[] = [
      {
        text: `Subir nueva ${label}`,
        icon: 'camera-outline',
        handler: () => {
          this.executePhotoUpload(type);
        },
      },
    ];

    if (hasCurrentPhoto) {
      buttons.push({
        text: `Eliminar ${label}`,
        role: 'destructive',
        icon: 'trash-outline',
        handler: () => {
          this.removePhoto(type);
        },
      });
    }

    buttons.push({
      text: 'Cancelar',
      role: 'cancel',
      icon: 'close-outline',
    });

    const sheet = await this.actionSheetCtrl.create({
      header: `Opciones de ${label}`,
      buttons,
    });
    await sheet.present();
  }

  /**
   * Elimina la foto del perfil del usuario persistiendo la remoción en backend.
   * @param type Tipo de recurso a limpiar ('AVATAR' o 'COVER').
   */
  private async removePhoto(type: 'AVATAR' | 'COVER'): Promise<void> {
    await this.ui.showLoading('Eliminando foto...');
    try {
      const field = type === 'AVATAR' ? 'avatarUrl' : 'coverUrl';
      const updated = await this.userService.updateProfile({ [field]: '' });
      this.viewedUser.set(updated);
      this.authService.currentUser.set(updated);
      await this.ui.dismissLoading();
      this.ui.showToast('Foto eliminada correctamente', 'success');
    } catch {
      await this.ui.dismissLoading();
      this.ui.showToast('No se pudo eliminar la foto', 'danger');
    }
  }

  /**
   * Ejecuta la captura desde la cámara o galería y la carga al servidor.
   * @param type Tipo de recurso ('AVATAR' o 'COVER').
   */
  private async executePhotoUpload(type: 'AVATAR' | 'COVER'): Promise<void> {
    try {
      const image = await Camera.getPhoto({
        quality: 90,
        source: CameraSource.Photos,
        resultType: CameraResultType.Uri,
        allowEditing: true,
      });
      if (image.webPath) {
        await this.ui.showLoading('Subiendo...');
        const response = await fetch(image.webPath);
        const blob = await response.blob();
        const uploadType = type === 'AVATAR' ? 'avatar' : 'cover';
        const { url } = await this.userService.uploadImage(
          blob,
          uploadType,
          image.format
        );

        const current = this.viewedUser();
        if (current) {
          const updated = {
            ...current,
            [type === 'AVATAR' ? 'avatarUrl' : 'coverUrl']: url,
          };
          this.viewedUser.set(updated);
          this.authService.currentUser.set(updated);
        }
        await this.ui.dismissLoading();
        this.ui.showToast('Foto actualizada correctamente', 'success');
      }
    } catch {
      logger.warn('Carga de imagen cancelada');
    }
  }
}

/**
 * @file map-tracker.component.ts
 * @sdd Dumb component que renderiza el trazo Polyline y los pines de observación.
 */
import {
  Component,
  ChangeDetectionStrategy,
  ViewChild,
  ElementRef,
  AfterViewInit,
  OnDestroy,
  input,
  effect,
} from '@angular/core';

import { IRouteSighting } from '../../../../../../../../shared/models/routes.interface';
import * as L from 'leaflet';

/**
 *
 */
@Component({
  selector: 'app-map-tracker',
  standalone: true,
  imports: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="map-placeholder">
      <div class="hud">
        <div class="metric">📍 {{ path().length || 0 }} Puntos</div>
        <div class="metric">🦅 {{ sightings().length || 0 }} Avistamientos</div>
      </div>
      <div class="map-canvas" #mapContainer></div>
    </div>
  `,
  styleUrls: ['./map-tracker.component.scss'],
})
export class MapTrackerComponent implements AfterViewInit, OnDestroy {
  /**
   *
   */
  path = input<[number, number][]>([]);
  /**
   *
   */
  sightings = input<IRouteSighting[]>([]);

  /**
   *
   */
  @ViewChild('mapContainer', { static: false }) mapContainer!: ElementRef;
  /**
   *
   */
  private map!: L.Map;
  /**
   *
   */
  private polyline!: L.Polyline;
  /**
   *
   */
  private markerLayer = L.layerGroup();

  /**
   *
   */
  private userMarker!: L.Marker;
  /**
   *
   */
  private firstPanDone = false;

  /**
   * Actualiza el mapa cuando los inputs del componente cambian.
   */
  ngAfterViewInit() {
    this.initMap();
  }

  /**
   *
   */
  constructor() {
    effect(() => {
      const currentPath = this.path();
      const currentSightings = this.sightings();

      if (this.map) {
        if (currentPath && currentPath.length > 0) {
          // leaflet uses [lat, lng], path is [lng, lat]
          const latLngs = currentPath.map((p) => [p[1], p[0]] as [number, number]);
          const currentPos = latLngs[latLngs.length - 1];

          this.polyline.setLatLngs(latLngs);

          if (!this.firstPanDone) {
            this.map.setView(currentPos, 17);
            this.firstPanDone = true;
          } else {
            this.map.panTo(currentPos);
          }

          // Update User Marker
          if (!this.userMarker) {
            const userIcon = L.divIcon({
              className: 'user-pulse-icon',
              html: '<div class="pulse-dot"></div>',
              iconSize: [18, 18],
              iconAnchor: [9, 9],
            });
            this.userMarker = L.marker(currentPos, { icon: userIcon, zIndexOffset: 1000 }).addTo(
              this.map,
            );
          } else {
            this.userMarker.setLatLng(currentPos);
          }
        }

        if (currentSightings) {
          this.markerLayer.clearLayers();

          const birdIcon = L.divIcon({
            className: 'bird-sighting-icon',
            html: '<div class="bird-sighting-icon__dot"></div>',
            iconSize: [18, 18],
            iconAnchor: [9, 9],
          });

          currentSightings.forEach((s) => {
            const dateObj = new Date(s.timestamp);
            const dateStr = dateObj.toLocaleDateString();
            const timeStr = dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const sRecord = s as unknown as {
              /**
               *
               */
              birdInfo?: Record<string, string>
              /**
               *
               */;
              bird_id: string;
            };
            const scientificName =
              sRecord.birdInfo?.['scientific_name'] || `Ave ID: ${sRecord.bird_id}`;
            const englishName = sRecord.birdInfo?.['english_name'] || '';

            const popupHtml = `
              <div class="bird-popup">
                <strong class="bird-popup__title">${scientificName}</strong><br>
                ${englishName ? `<span class="bird-popup__subtitle">${englishName}</span><br>` : ''}
                <span class="bird-popup__meta">📅 ${dateStr} - 🕒 ${timeStr}</span><br>
                <span class="bird-popup__detail"><strong>Cantidad:</strong> ${s.quantity}</span>
                ${
                  s.details
                    ? `<br><span class="bird-popup__detail"><strong>Detalle:</strong> ${s.details}</span>`
                    : ''
                }
              </div>
            `;
            const m = L.marker([s.lat, s.lng], { icon: birdIcon }).bindPopup(popupHtml);
            this.markerLayer.addLayer(m);
          });
        }
      }
    });
  }

  /**
   *
   */
  private initMap() {
    this.map = L.map(this.mapContainer.nativeElement).setView([4.5709, -74.2973], 5);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap FlockApp',
      crossOrigin: true,
    }).addTo(this.map);

    this.polyline = L.polyline([], { color: 'blue', weight: 4 }).addTo(this.map);
    this.markerLayer.addTo(this.map);

    // Ionic layout delay fix: ensure leaflet recalculates dimensions
    setTimeout(() => {
      this.map.invalidateSize();
    }, 400);
  }

  /**
   *
   */
  ngOnDestroy() {
    if (this.map) {
      this.map.remove();
    }
  }
}

/**
 * @sdd
 * [Objetivo]: Página de Configuración y Gestión de Permisos Android (Google Play Store compliance), donde el usuario puede auditar y modificar permisos de Cámara, Ubicación GPS y Multimedia.
 * [I/O - Reusabilidad]: Consume AppPermissionsService (Signals), NetworkService y UiService. Rutas asociadas: /home/settings.
 * [Edge Cases - UI]: Manejo de estados Concedido/Denegado/Pendiente, feedback táctil háptico y guía para permisos bloqueados en Ajustes de Android.
 */
import { Component, ChangeDetectionStrategy, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  IonHeader,
  IonToolbar,
  IonButtons,
  IonMenuButton,
  IonContent,
  IonIcon,
  IonButton,
  IonChip,
} from '@ionic/angular';
import { addIcons } from 'ionicons';
import {
  settingsOutline,
  cameraOutline,
  locationOutline,
  imagesOutline,
  shieldCheckmarkOutline,
  informationCircleOutline,
  checkmarkCircle,
  closeCircle,
  warningOutline,
  openOutline,
  wifiOutline,
  phonePortraitOutline,
  lockClosedOutline,
} from 'ionicons/icons';
import { AppPermissionsService, AppPermissionState } from '../../core/services/app-permissions.service';
import { NetworkService } from '../../core/services/network.service';
import { UiService } from '../../core/services/ui.service';

@Component({
  selector: 'app-settings',
  templateUrl: './settings.page.html',
  styleUrls: ['./settings.page.scss'],
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    IonHeader,
    IonToolbar,
    IonButtons,
    IonMenuButton,
    IonContent,
    IonIcon,
    IonButton,
    IonChip,
  ],
})
/**
 * Componente principal de la página de Configuración y Gestión de Permisos.
 */
export class SettingsPage implements OnInit {
  /** Inyección del servicio de permisos */
  public readonly permissionsService = inject(AppPermissionsService);

  /** Inyección del servicio de red */
  public readonly networkService = inject(NetworkService);

  /** Inyección del servicio de UI para alertas */
  private readonly ui = inject(UiService);

  /**
   * Registra los iconos usados en la página de configuración.
   */
  constructor() {
    addIcons({
      settingsOutline,
      cameraOutline,
      locationOutline,
      imagesOutline,
      shieldCheckmarkOutline,
      informationCircleOutline,
      checkmarkCircle,
      closeCircle,
      warningOutline,
      openOutline,
      wifiOutline,
      phonePortraitOutline,
      lockClosedOutline,
    });
  }

  /**
   * Ciclo de vida: Refresca el estado de permisos al abrir la vista.
   */
  async ngOnInit(): Promise<void> {
    await this.permissionsService.checkAllPermissions();
  }

  /**
   * Solicita el permiso de cámara a través de la modal de revelación Google Play.
   */
  async requestCamera(): Promise<void> {
    const granted = await this.permissionsService.requestCameraWithRationale();
    if (granted) {
      await this.ui.showToast('Permiso de Cámara activado con éxito', 'success');
    }
  }

  /**
   * Solicita el permiso de ubicación GPS a través de la modal de revelación Google Play.
   */
  async requestLocation(): Promise<void> {
    const granted = await this.permissionsService.requestLocationWithRationale();
    if (granted) {
      await this.ui.showToast('Permiso de Ubicación (GPS) activado con éxito', 'success');
    }
  }

  /**
   * Solicita el permiso de galería de fotos.
   */
  async requestPhotos(): Promise<void> {
    const granted = await this.permissionsService.requestPhotosWithRationale();
    if (granted) {
      await this.ui.showToast('Permiso de Galería activado con éxito', 'success');
    }
  }

  /**
   * Muestra las instrucciones para modificar permisos en la configuración de Android.
   */
  async openSystemGuide(): Promise<void> {
    await this.permissionsService.showDeviceSettingsGuide('camera');
  }

  /**
   * Retorna la etiqueta legible del estado de un permiso.
   * @param status Estado consolidado del permiso
   * @returns Etiqueta amigable en español
   */
  getStatusLabel(status: AppPermissionState): string {
    switch (status) {
      case 'granted':
        return 'Permitido';
      case 'denied':
        return 'Denegado';
      case 'prompt':
      default:
        return 'Pendiente';
    }
  }
}

